/* Local management screens. External delivery and authorization require server integrations. */
(() => {
  'use strict';
  const state = {cms:'content',communication:'inbox',settings:'organization'};
  const api = () => window.Seva;
  const db = () => api().db;
  const esc = value => api().esc(value == null ? '' : String(value));
  const ico = (name,size=18) => api().icon(name,size);
  const button = (label,action,attrs='',kind='') => `<button type="button" class="btn ${kind}" data-action="${action}" ${attrs}>${label}</button>`;
  const tag = (label,kind='neutral') => `<span class="badge ${kind}">${esc(label)}</span>`;
  const tabs = (section,items) => `<div class="tabs">${items.map(([id,label])=>`<button type="button" class="${state[section]===id?'active':''}" data-action="sys-${section}-tab" data-tab="${id}">${label}</button>`).join('')}</div>`;
  const head = (title,caption='',action='') => `<div class="panel-head" style="padding-bottom:20px"><div><h2 class="panel-title">${title}</h2>${caption?`<p class="panel-caption">${caption}</p>`:''}</div>${action}</div>`;
  const panel = (title,caption,body,action='') => `<section class="panel">${head(title,caption,action)}${body}</section>`;
  const note = (body,kind='info') => `<div class="notice ${kind}">${ico('info',17)}<span>${body}</span></div>`;
  const today = () => new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});
  const dt = value => api().date(value);
  const empty = (title,desc) => `<div class="empty-state">${ico('inbox',30)}<h3>${title}</h3><p>${desc}</p></div>`;
  const field = (key,label,value,opts={}) => `<div class="field ${opts.full?'full':''}"><label for="sys-${key}">${label}</label>${opts.area?`<textarea id="sys-${key}" name="${key}" ${opts.required?'required':''} maxlength="${opts.max||3000}">${esc(value)}</textarea>`:`<input id="sys-${key}" name="${key}" type="${opts.type||'text'}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!=null?`min="${opts.min}"`:''} ${opts.maxlength?`maxlength="${opts.maxlength}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>`}${opts.hint?`<small>${opts.hint}</small>`:''}</div>`;
  const defaultsMenu = () => [{id:'about',label:'Who we are',visible:true},{id:'projects',label:'Our work',visible:true},{id:'events',label:'Events',visible:true},{id:'stories',label:'Stories',visible:true},{id:'contact',label:'Contact',visible:true}];

  function orgFields(context) {
    const s=db().settings || {};
    const about = context==='cms';
    return `<form id="sys-org-form" class="settings-form" data-context="${context}"><div class="form-grid">${field('name','Foundation name',s.name,{required:true,full:true,maxlength:120})}${field('tagline','Tagline',s.tagline,{full:true,maxlength:200})}${field('mission','Our mission',s.mission,{area:true,full:true,required:true})}${field('vision','Our vision',s.vision,{area:true,full:true,required:true})}${field('email','Business email',s.email,{type:'email',placeholder:'you@your-domain.org',hint:'Use an email address you already own.'})}${field('phone','Call button number',s.phone,{type:'tel',placeholder:'+91 …'})}${field('whatsapp','WhatsApp number',s.whatsapp,{type:'tel',placeholder:'+91 …',hint:'Shown as a chat link after a valid number is saved.'})}${field('mapUrl','Google Maps location link',s.mapUrl,{type:'url',placeholder:'https://maps.google.com/…'})}${field('address','Office / contact address',s.address,{area:true,full:true})}${field('youtube','YouTube channel URL',s.youtube,{type:'url',placeholder:'https://www.youtube.com/@…'})}${field('facebook','Facebook page URL',s.facebook,{type:'url',placeholder:'https://www.facebook.com/…'})}${field('instagram','Instagram URL',s.instagram,{type:'url',placeholder:'https://www.instagram.com/…'})}${field('analyticsId','Google Analytics measurement ID',s.analyticsId,{hint:'Loads Google Analytics on public pages after a valid measurement ID is saved.',placeholder:'G-XXXXXXXXXX'})}${about?'':`${field('membershipFee','Annual membership fee (₹)',s.membershipFee,{type:'number',min:0})}${field('receiptPrefix','Receipt prefix',s.receiptPrefix,{maxlength:12})}${field('fiscalYear','Financial year',s.fiscalYear,{maxlength:20})}`}</div><div class="form-actions"><small style="margin-right:auto;color:var(--muted);font-size:10px">Saved in this browser</small><button class="btn primary" type="submit">${ico('check',15)} Save ${about?'website content':'foundation settings'}</button></div></form>`;
  }

  function renderCMS() {
    let body='';
    if(state.cms==='content') {
      body=`<div class="settings-grid" style="margin-top:22px">${panel('Make this website yours','Update the foundation story and contact information.',orgFields('cms'))}<div>${panel('Your public website','A welcoming home for your community.',`<div style="padding:0 22px 22px"><div style="background:var(--mint);border-radius:7px;padding:24px;margin-bottom:18px;color:var(--green)">${ico('globe',32)}<h3 style="font-size:17px;margin:13px 0 8px">A bridge to a better tomorrow.</h3><p style="font-size:11px;line-height:1.8">Introduce your foundation, share your work, and invite members, volunteers and supporters.</p></div>${button('Open website preview →','sys-preview','','primary')}<p style="font-size:10px;line-height:1.8;color:var(--muted);margin-top:16px">The public view uses your saved mission, vision, contact links and navigation. Programs and photographs remain illustrative until you replace them.</p></div>`)}<div style="height:20px"></div>${panel('Content checklist','Build trust with clear information.',`<div class="list-rows">${[['Mission & vision',!!db().settings.mission],['Foundation email',!!db().settings.email],['Phone / WhatsApp',!!(db().settings.phone||db().settings.whatsapp)],['Contact location',!!db().settings.mapUrl]].map(([label,ok])=>`<div class="list-row"><strong>${label}</strong>${tag(ok?'Added':'To add',ok?'':'warning')}</div>`).join('')}</div>`)}</div></div>`;
    } else if(state.cms==='news') {
      body=`<div style="margin-top:22px">${panel('Blog & foundation news','Draft and maintain stories for your community.',`<div class="list-rows">${(db().news||[]).map(n=>`<div class="list-row"><div><strong>${esc(n.title)}</strong><p>${esc(n.body).slice(0,190)}${String(n.body||'').length>190?'…':''}</p><p>${dt(n.date)} · ${esc(n.status||'Draft')}</p></div><div style="display:flex;gap:8px">${button('Edit','sys-news-edit',`data-id="${esc(n.id)}"`,'small')}${button('Remove','sys-news-remove',`data-id="${esc(n.id)}"`,'small danger')}</div></div>`).join('')||empty('No stories yet','Share a programme update or a community story.')}</div>`,button('+ Add news','sys-news-new','','primary'))}</div>`;
    } else if(state.cms==='gallery') {
      body=`<div class="module-grid" style="margin-top:22px">${db().projects.map(p=>`<article class="project-card"><img src="${esc(p.image)}" alt="${esc(p.name)} project photograph" loading="lazy"><div class="project-card-body">${tag('Illustrative project image')}<h3>${esc(p.name)}</h3><p>Replace the photo URL in the project editor with a photograph you have permission to use.</p>${button('Edit project & photo','sys-project-edit',`data-id="${esc(p.id)}"`)}</div></article>`).join('')}</div>`;
    } else if(state.cms==='menu') {
      const menu=db().settings.publicMenu || defaultsMenu();
      body=`<div style="margin-top:22px">${panel('Public navigation','Choose labels and visible links for the website header.',`<form id="sys-menu-form" class="settings-form"><div class="list-rows" style="padding:0">${menu.map(m=>`<div class="list-row"><div class="field" style="flex:1"><label for="sys-menu-${esc(m.id)}">${esc(m.id.charAt(0).toUpperCase()+m.id.slice(1))} section</label><input id="sys-menu-${esc(m.id)}" name="label-${esc(m.id)}" value="${esc(m.label)}" maxlength="32" required></div><label style="font-size:11px;display:flex;gap:8px;align-items:center"><input type="checkbox" name="visible-${esc(m.id)}" ${m.visible?'checked':''}> Show in navigation</label></div>`).join('')}</div><div class="form-actions"><button type="submit" class="btn primary">Save navigation</button></div></form>`)}</div>`;
    }
    return `<div class="panel">${tabs('cms',[['content','Website content'],['news','Blog & news'],['gallery','Project gallery'],['menu','Menu management']])}</div>${body}`;
  }

  function renderInbox() {
    return panel('Enquiry inbox','Member messages and public enquiries saved in this browser.',`<div class="list-rows">${(db().messages||[]).map(m=>`<div class="list-row"><div style="flex:1"><div style="display:flex;gap:9px;align-items:center"><strong>${esc(m.subject||'Foundation enquiry')}</strong>${tag(m.status||'New',m.status==='New'?'warning':'neutral')}</div><p>${esc(m.name)} · ${esc(m.email)} · ${dt(m.date)}</p><p>${esc(m.body).slice(0,160)}${String(m.body||'').length>160?'…':''}</p>${m.notes?.length?`<p>${m.notes.length} local reply note${m.notes.length>1?'s':''}</p>`:''}</div>${button('Open enquiry','sys-message-open',`data-id="${esc(m.id)}"`,'small')}</div>`).join('')||empty('All caught up','New enquiries will appear here.')}</div>`,button('+ Add enquiry','sys-enquiry-new','','primary'));
  }
  function renderCommunication() {
    let body='';
    if(state.communication==='inbox')body=renderInbox();
    if(state.communication==='notices')body=`<div style="display:flex;justify-content:flex-end;margin-bottom:16px">${button('+ Compose notice','sys-notice-new','','primary')}</div>${(db().notices||[]).map(n=>`<article class="notice-card"><div style="display:flex;gap:15px;align-items:center;justify-content:space-between"><h3>${esc(n.title)}</h3>${tag('Published locally')}</div><p>${esc(n.body)}</p><div class="notice-meta"><span>${dt(n.date)}</span><span>${esc(n.audience||'Everyone')}</span>${n.memberId?`<span>${esc(n.memberId)}</span>`:''}</div></article>`).join('')||empty('No notices yet','Create a notice for one member or your whole community.')}`;
    if(state.communication==='reminders') {
      const expiry = (db().members||[]).filter(m=>m.status!=='Blocked'&&m.validity&&new Date(m.validity+'T23:59:59+05:30')<=new Date(Date.now()+30*86400000));
      body=panel('Membership renewal desk','Members expiring within the next 30 days, including expired memberships.',`<div class="list-rows">${expiry.map(m=>`<div class="list-row"><div><strong>${esc(m.name)}</strong><p>${esc(m.id)} · Valid until ${dt(m.validity)}</p></div>${button('Create reminder','sys-renew-reminder',`data-id="${esc(m.id)}"`,'small')}</div>`).join('')||empty('No renewals due','Memberships expiring soon will appear here.')}</div>`);
    }
    return note('Messages and notices are stored locally. Email, SMS and WhatsApp delivery require a connected messaging service; no external messages are sent.')+`<div class="mini-stats"><div class="mini-stat"><small>New enquiries</small><strong>${(db().messages||[]).filter(m=>m.status==='New').length}</strong></div><div class="mini-stat"><small>Local notices</small><strong>${(db().notices||[]).length}</strong></div><div class="mini-stat"><small>Delivery channels connected</small><strong>0</strong></div></div><div class="panel">${tabs('communication',[['inbox','Enquiry inbox'],['notices','Member notices'],['reminders','Renewal reminders']])}</div><div style="margin-top:22px">${body}</div>`;
  }
  const permissionModules=['Dashboard','Members','Donations','Volunteers','Projects','Staff','Documents','Accounting','Events','Website CMS','Communication','Admin'];
  const roles=['Super Admin','Admin','Employee','Member'];
  function permissionDefault(module,role) {return role==='Super Admin'||(role==='Admin'&&module!=='Admin')||(role==='Employee'&&['Dashboard','Volunteers','Projects','Documents','Events'].includes(module))||(role==='Member'&&['Dashboard','Documents','Events'].includes(module));}
  function renderAccess() {
    return note('Role settings are a configuration preview. This browser demo has no authentication service or server-enforced permissions. Do not enter private personal or financial data.')+`<div class="role-grid" style="margin-bottom:22px">${[['Super Admin','Foundation-wide settings and access.'],['Admin','Day-to-day records and programme coordination.'],['Employee','Assigned activities and documents.'],['Member','Personal membership and community updates.']].map(([r,p])=>`<div class="role-card">${ico('shield',25)}<h3>${r}</h3><p>${p}</p>${tag('Configuration preview')}</div>`).join('')}</div>${panel('Role & permission configuration','Save your intended module access before connecting production authentication.',`<form id="sys-permissions-form" class="settings-form"><div class="table-wrap"><table class="permissions-table"><thead><tr><th>Module</th>${roles.map(r=>`<th>${r}</th>`).join('')}</tr></thead><tbody>${permissionModules.map((mod,i)=>`<tr><td>${mod}</td>${roles.map((role,j)=>{const key=mod+':'+role;const checked=db().permissions?.[key]??permissionDefault(mod,role);return `<td><input aria-label="${esc(role+' access to '+mod)}" type="checkbox" name="p-${i}-${j}" ${checked?'checked':''} ${role==='Super Admin'?'disabled':''}></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="form-actions"><button type="submit" class="btn primary">Save configuration</button></div></form>`)}`;
  }
  function renderServices() {
    const list=[['Site hosting','Provided by Sites','Your published site is served over HTTPS.'],['SSL certificate','Included with hosting','HTTPS is supplied on the published Sites address.'],['Custom domain','Not connected','A domain you own can be connected after publication. Domain purchase is separate.'],['Business email','Not provisioned','Add an address you own to the foundation settings. Mailbox hosting requires an email provider.'],['Payment gateway','Not connected','Donation forms record pledges and manual entries. No online payment is taken.'],['Email / SMS delivery','Not connected','Notices and reply notes currently remain in this browser.'],['WhatsApp chat link',db().settings.whatsapp?'Number configured':'Add your number','A chat button opens WhatsApp; automated messaging is not configured.'],['Google Maps',db().settings.mapUrl?'Location link configured':'Add your location','A saved location link appears in the public contact section.'],['Google Analytics',db().settings.analyticsId?'Configured for public pages':'Not configured','Add a valid measurement ID to load Google Analytics on your public website.'],['Social accounts & YouTube','Use existing account URLs','Add your profile URLs in Website CMS. New accounts have not been created.'],['Technical support','No support contract configured','A one-year support service requires an agreement with your service provider.']];
    return panel('Connected services & launch readiness','Clear configuration status for the foundation website.',`<div class="list-rows">${list.map(([title,status,desc])=>`<div class="list-row"><div><strong>${title}</strong><p>${desc}</p></div>${tag(status,/Included|Provided|configured/.test(status)?'':'warning')}</div>`).join('')}</div>`);
  }
  function renderBackup() {
    return `<div class="settings-grid">${panel('Your local data','Export a copy before moving to another browser.',`<div class="settings-form"><p style="font-size:12px;color:var(--text);line-height:1.8;margin-bottom:20px">Records are saved in this browser’s local storage. They are not shared across devices or protected by account-level access. A backup includes sample records and your local edits.</p>${button('Download backup JSON','sys-backup','','primary')}<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3 style="font-size:13px;margin-bottom:12px">Restore from a backup</h3><p style="font-size:11px;color:var(--muted);line-height:1.8;margin-bottom:14px">Choose a backup exported from this workspace. You can review its record counts before replacing the corresponding local records.</p><input id="sys-backup-file" type="file" accept="application/json,.json" style="font-size:11px;max-width:100%"></div>`)}${panel('Storage & privacy','Designed for a reviewable local demonstration.',`<div class="list-rows"><div class="list-row"><div><strong>Browser-local storage</strong><p>Edits persist on this device and browser.</p></div>${tag('Local')}</div><div class="list-row"><div><strong>Illustrative records</strong><p>Use sample data while configuring the site.</p></div>${tag('Demo')}</div><div class="list-row"><div><strong>Automatic cloud backup</strong><p>A server database and backup schedule are not connected.</p></div>${tag('Not connected','warning')}</div><div class="list-row"><div><strong>Content protection</strong><p>Private hosting controls who can open this Site. Additional record-level security needs a backend.</p></div>${tag('Needs backend','warning')}</div></div>`)}</div>`;
  }
  function renderSettings() {
    let body='';
    if(state.settings==='organization')body=panel('Foundation details','One place for your organization’s content and preferences.',orgFields('settings'));
    if(state.settings==='access')body=renderAccess();
    if(state.settings==='services')body=renderServices();
    if(state.settings==='activity')body=panel('Activity history','Actions recorded in this browser. This is not a security audit trail.',`<div class="list-rows">${(db().logs||[]).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,100).map(log=>`<div class="list-row"><span class="activity-dot"></span><div style="flex:1"><strong>${esc(log.action)}</strong><p>${esc(log.actor||'Demo administrator')} · ${dt(log.date)}</p></div>${tag('Local activity')}</div>`).join('')||empty('No activity yet','Workspace changes appear here.')}</div>`);
    if(state.settings==='backup')body=renderBackup();
    return `<div class="panel">${tabs('settings',[['organization','Foundation settings'],['access','Roles & permissions'],['services','Connected services'],['activity','Activity history'],['backup','Backup & restore']])}</div><div style="margin-top:22px">${body}</div>`;
  }
  window.renderSystemPage = route => route==='cms'?renderCMS():route==='communication'?renderCommunication():route==='settings'?renderSettings():'';

  let stagedBackup=null;
  function openMessage(id) {
    const m=(db().messages||[]).find(x=>x.id===id); if(!m)return;
    if(m.status==='New'){m.status='Read';if(api().save('Enquiry opened: '+(m.subject||m.name))!==false)api().render();}
    api().modal('Enquiry details',`<div class="notice info"><span>Local reply notes are saved with this enquiry. They are not emailed or messaged to the sender.</span></div><h3 style="font-size:15px;margin-bottom:8px">${esc(m.subject||'Foundation enquiry')}</h3><p style="font-size:11px;color:var(--muted);margin-bottom:18px">${esc(m.name)} · ${esc(m.email)} · ${dt(m.date)}</p><p style="font-size:13px;line-height:1.9;white-space:pre-wrap;margin-bottom:22px">${esc(m.body)}</p>${(m.notes||[]).map(n=>`<div class="notice"><span><strong>Local reply note · ${dt(n.date)}</strong><br>${esc(n.body)}</span></div>`).join('')}<form id="sys-reply-form" data-id="${esc(m.id)}"><div class="field"><label for="sys-reply-note">Reply note</label><textarea id="sys-reply-note" name="body" maxlength="3000" required placeholder="Save a follow-up note for your team…"></textarea></div><div class="form-actions"><button type="button" class="btn" data-action="sys-message-resolve" data-id="${esc(m.id)}">Mark resolved</button><button type="submit" class="btn primary">Save reply note</button></div></form>`,'Enquiry and member communication');
    window.bindSystemForms();
  }
  function backupDownload() {
    const name='seva-setu-backup-'+today()+'.json';
    const payload={format:'seva-setu-backup',version:1,exportedAt:new Date().toISOString(),data:db()};
    if(window.downloadFoundationJSON)window.downloadFoundationJSON(name,payload);
    else {const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
    api().toast('Backup downloaded');
  }
  window.handleSystemAction = (action,el) => {
    const id=el?.dataset.id;
    if(action==='sys-cms-tab'||action==='sys-communication-tab'||action==='sys-settings-tab'){const section=action.split('-')[1];state[section]=el.dataset.tab;api().render();return true;}
    if(action==='sys-preview'){window.navigate('website');return true;}
    if(action==='sys-news-new'){api().openForm('news');return true;}
    if(action==='sys-news-edit'){api().openForm('news',{editId:id});return true;}
    if(action==='sys-news-remove'){const n=db().news.find(x=>x.id===id);if(n)api().modal('Remove news story',`<p style="font-size:12px;line-height:1.8">Remove “${esc(n.title)}” from your local news records?</p><div class="form-actions">${button('Cancel','sys-close')}${button('Remove story','sys-news-confirm-remove',`data-id="${esc(id)}"`,'danger')}</div>`);return true;}
    if(action==='sys-news-confirm-remove'){db().news=db().news.filter(x=>x.id!==id);api().save('News story removed');api().closeModal();api().render();api().toast('Story removed');return true;}
    if(action==='sys-project-edit'){api().openForm('project',{editId:id});return true;}
    if(action==='sys-enquiry-new'){api().openForm('enquiry');return true;}
    if(action==='sys-notice-new'){api().openForm('notice');return true;}
    if(action==='sys-message-open'){openMessage(id);return true;}
    if(action==='sys-message-resolve'){const m=db().messages.find(x=>x.id===id);if(m){m.status='Resolved';api().save('Enquiry marked resolved');api().closeModal();api().render();api().toast('Enquiry marked resolved');}return true;}
    if(action==='sys-renew-reminder'){const m=db().members.find(x=>x.id===id);if(m){db().notices.unshift({id:'SSF-N-'+Date.now(),title:'Membership renewal reminder',body:`Dear ${m.name}, your membership ${m.id} is valid until ${dt(m.validity)}. Please submit a renewal request to stay connected with Seva Setu Foundation.`,audience:m.name,memberId:m.id,date:today(),status:'Published locally'});api().save('Local renewal reminder created for '+m.name);api().toast('Renewal notice created locally');}return true;}
    if(action==='sys-backup'){backupDownload();return true;}
    if(action==='sys-close'){stagedBackup=null;api().closeModal();return true;}
    if(action==='sys-restore-confirm'){if(stagedBackup){const imported=stagedBackup;stagedBackup=null;Object.keys(imported).forEach(key=>{if(!['__proto__','prototype','constructor'].includes(key))db()[key]=imported[key];});api().save('Workspace restored from local backup');api().closeModal();api().render();api().toast('Backup restored in this browser');}return true;}
    return false;
  };
  window.bindSystemForms = function () {
    const org=document.getElementById('sys-org-form');
    if(org&&!org.dataset.bound){org.dataset.bound='true';org.addEventListener('submit',event=>{event.preventDefault();if(!org.reportValidity())return;const values=Object.fromEntries(new FormData(org));for(const key of ['mapUrl','youtube','facebook','instagram']){if(values[key]){try{const url=new URL(values[key]);if(url.protocol!=='https:')throw Error();}catch{api().toast('Please use a valid HTTPS link for '+key);return;}}}if(values.analyticsId&&!/^G-[A-Z0-9]{6,20}$/i.test(values.analyticsId)){api().toast('Use a measurement ID such as G-XXXXXXXXXX');return;}if(values.membershipFee!=null)values.membershipFee=Number(values.membershipFee);for(const key in values)if(typeof values[key]==='string')values[key]=values[key].trim();Object.assign(db().settings,values);window.foundationSettings=db().settings;if(api().save('Foundation settings updated')===false)return;api().render();api().toast('Foundation details saved');});}
    const menu=document.getElementById('sys-menu-form');
    if(menu&&!menu.dataset.bound){menu.dataset.bound='true';menu.addEventListener('submit',event=>{event.preventDefault();if(!menu.reportValidity())return;const values=new FormData(menu);db().settings.publicMenu=defaultsMenu().map(m=>({...m,label:String(values.get('label-'+m.id)||m.label).trim(),visible:values.has('visible-'+m.id)}));if(api().save('Website navigation updated')===false)return;api().toast('Website navigation saved');});}
    const perms=document.getElementById('sys-permissions-form');
    if(perms&&!perms.dataset.bound){perms.dataset.bound='true';perms.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(perms), permissions={};permissionModules.forEach((mod,i)=>roles.forEach((role,j)=>{permissions[mod+':'+role]=role==='Super Admin'||values.has('p-'+i+'-'+j);}));db().permissions=permissions;if(api().save('Permission configuration saved (preview only)')===false)return;api().toast('Permission configuration saved');});}
    const reply=document.getElementById('sys-reply-form');
    if(reply&&!reply.dataset.bound){reply.dataset.bound='true';reply.addEventListener('submit',event=>{event.preventDefault();if(!reply.reportValidity())return;const body=String(new FormData(reply).get('body')||'').trim();if(!body)return;const m=db().messages.find(x=>x.id===reply.dataset.id);if(!m)return;m.notes=m.notes||[];m.notes.push({body,date:today()});m.status='In progress';if(api().save('Local reply note added')===false)return;api().closeModal();api().render();api().toast('Reply note saved locally');});}
    const file=document.getElementById('sys-backup-file');
    if(file&&!file.dataset.bound){file.dataset.bound='true';file.addEventListener('change',async()=>{const f=file.files?.[0];if(!f)return;if(f.size>5*1024*1024){api().toast('Choose a backup smaller than 5 MB');file.value='';return;}try{const raw=JSON.parse(await f.text(),(key,value)=>{if(['__proto__','constructor','prototype'].includes(key))throw new Error('Unsupported backup key');return value;});const data=raw?.format==='seva-setu-backup'?raw.data:raw;if(!data||typeof data!=='object'||Array.isArray(data)||!Array.isArray(data.members)||!Array.isArray(data.donations)||!data.settings||typeof data.settings!=='object'||Array.isArray(data.settings))throw new Error('Not a foundation backup');const lists=['members','donors','donations','volunteers','projects','staff','expenses','events','applications','attendance','notices','messages','tasks','news','logs'];for(const key of lists){if(data[key]!=null&&(!Array.isArray(data[key])||data[key].some(x=>!x||typeof x!=='object'||Array.isArray(x)||typeof x.id!=='string'||!x.id)))throw new Error('Invalid records in '+key);}const requiredFields={members:['name','email','joined','validity','status','department','role'],donors:['name','email'],donations:['name','email','project','date','status','method'],volunteers:['name','email','skills','department','status','joined'],projects:['name','category','status','location','description','lead','startDate','endDate'],staff:['name','email','role','department','joined','status'],expenses:['title','project','category','vendor','date','method','status'],events:['name','date','time','location','description','status'],applications:['name','email','type','date','status'],attendance:['personId','name','date','status'],notices:['title','body','audience','date','status'],messages:['name','email','subject','body','date','status'],tasks:['title','assignee','project','due','status'],news:['title','body','date','status'],logs:['action','date','actor']};for(const [key,fields] of Object.entries(requiredFields)){for(const row of data[key]||[]){if(!/^[A-Za-z0-9_-]{1,100}$/.test(row.id)||fields.some(field=>typeof row[field]!=='string'))throw new Error('Invalid '+key+' fields');for(const num of ['amount','budget','spent','raised','beneficiaries','progress','salary','capacity','registered','target','hours'])if(num in row&&(typeof row[num]!=='number'||!Number.isFinite(row[num])||row[num]<0))throw new Error('Invalid amount in '+key);}}if(typeof data.settings.name!=='string'||typeof data.settings.mission!=='string'||typeof data.settings.vision!=='string')throw new Error('Invalid foundation settings');if(data.settings.publicMenu!=null&&(!Array.isArray(data.settings.publicMenu)||data.settings.publicMenu.some(m=>!m||!['about','projects','events','stories','contact'].includes(m.id)||typeof m.label!=='string'||typeof m.visible!=='boolean')))throw new Error('Invalid menu');stagedBackup=data;api().modal('Restore this backup?',`<div class="notice"><span>This replaces the matching local records in this browser. Download a backup of your current records first if you need to keep them.</span></div><div class="mini-stats"><div class="mini-stat"><small>Members</small><strong>${data.members.length}</strong></div><div class="mini-stat"><small>Donations</small><strong>${data.donations.length}</strong></div><div class="mini-stat"><small>Projects</small><strong>${data.projects?.length||0}</strong></div></div><p style="font-size:12px;line-height:1.8">Foundation: ${esc(data.settings.name||'Seva Setu Foundation')}<br>Backup file: ${esc(f.name)}</p><div class="form-actions">${button('Cancel','sys-close')}${button('Restore local records','sys-restore-confirm','','primary')}</div>`,'Review the backup before restoring');}catch(error){stagedBackup=null;api().toast('This file is not a valid Seva Setu backup');file.value='';}});}
  };
})();
